from .base import EMSSInterface
import six


class FileManager(EMSSInterface):
    """
    EMSsim keywords related to files management
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(FileManager, self).__init__()

    def request_download(self, path, file_name, plan_id, activate=0, attachment=None, enb_id=None, bts_id=None, alias=None):
        """
        Requests file download of specific file type.

        :param path: Path to file on local filesystem (to be downloaded into eNodeB)
        :param file_name: Type of to-be-downloaded file. Supported file types:
            hwConfigurationFile
            configurationPlanFile
            logFile
            swFile
            licFile
            measurementFile
            rnwConfigurationPlanFile
            signalingPlanFile
            ipPlanFile
            alarmFile
            combinedSiteConfigurationPlanFile
            allConfigurationPlanFile
            locationLock
            testResultFile
            autoConfReport
            connectedFapInfoFile
            measurementPlanFile
            rnwMetadataFile
            topologyFile
            atmPlanFile
            subTopologyFile
            togglingParFile
            troubleShootingData
            fapTmplFile
            ipRangeFile
            ipSecPlanFile
            fapConfiguredPlanFile
            fapActivatedPlanFile
            fgwPlanFileWithoutMacroCells
            fgwCertExpiryFile
            fapCertExpiryFile
            fapScanResultFile
            fgwFcodesPlanFile
            fgwInseePlanFile
            fgwMacroDBPlanFile
            fgwFapsIpSecConnFailureFile
            fgwSecurityClonedHnbFile
        :param plan_id: Configuration change plan number [0..4294967295]
            In case of allConfigurationPlanFile(12) file type, this parameter should be identical to the id of attribute value
            inside the cmData element of to-be-downloaded XML file
        :param activate: (default 0)
        :param attachment: Path to attachment file on local filesystem (to be included in message)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +------------------+---------------------------------------------------------------+--------------------------+------------+------------+
        |                                                         Examples                                                                      |
        +==================+===============================================================+==========================+============+============+
        | request download | /home/flexi57/UPLOADS/CUPL_BTSA_57.xml                        | allconfigurationplanfile | 3221225472 | activate=1 |
        +------------------+---------------------------------------------------------------+--------------------------+------------+------------+
        """
        activate = self._opt_int(activate)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        file_type = self._map_filename_to_filetype(file_name)
        params = [path, file_type, plan_id]
        if activate:
            params.append('-activate')
        if attachment:
            params.append('-attachment {}'.format(attachment))
        self._assert(self._get_emssim().cmd_file_download().run(params), "File download operation failed")

    def request_upload(self, file_name, enb_id=None, bts_id=None, alias=None):
        """
        Requests file upload of specific file type.

        :param file_name: Type of to-be-uploaded file. Supported file types:
            hwConfigurationFile
            configurationPlanFile
            logFile
            swFile
            licFile
            measurementFile
            rnwConfigurationPlanFile
            signalingPlanFile
            ipPlanFile
            alarmFile
            combinedSiteConfigurationPlanFile
            allConfigurationPlanFile
            locationLock
            testResultFile
            autoConfReport
            connectedFapInfoFile
            measurementPlanFile
            rnwMetadataFile
            topologyFile
            atmPlanFile
            subTopologyFile
            togglingParFile
            troubleShootingData
            fapTmplFile
            ipRangeFile
            ipSecPlanFile
            fapConfiguredPlanFile
            fapActivatedPlanFile
            fgwPlanFileWithoutMacroCells
            fgwCertExpiryFile
            fapCertExpiryFile
            fapScanResultFile
            fgwFcodesPlanFile
            fgwInseePlanFile
            fgwMacroDBPlanFile
            fgwFapsIpSecConnFailureFile
            fgwSecurityClonedHnbFile
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------+--------------------------+
        |                  Examples                 |
        +================+==========================+
        | request upload | hwConfigurationFile      |
        +----------------+--------------------------+
        | request upload | allconfigurationplanfile |
        +----------------+--------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        file_type = self._map_filename_to_filetype(file_name)
        self._assert(self._get_emssim().cmd_file_upload().run(file_type), "File upload operation failed")

    def request_activate(self, file_name, planid, enb_id=None, bts_id=None, alias=None):
        """
        Triggers NE to activate just downloaded file.

        :param file_type: Type of to-be-downloaded file. Supported file types:
            hwConfigurationFile
            configurationPlanFile
            logFile
            swFile
            licFile
            measurementFile
            rnwConfigurationPlanFile
            signalingPlanFile
            ipPlanFile
            alarmFile
            combinedSiteConfigurationPlanFile
            allConfigurationPlanFile
            locationLock
            testResultFile
            autoConfReport
            connectedFapInfoFile
            measurementPlanFile
            rnwMetadataFile
            topologyFile
            atmPlanFile
            subTopologyFile
            togglingParFile
            troubleShootingData
            fapTmplFile
            ipRangeFile
            ipSecPlanFile
            fapConfiguredPlanFile
            fapActivatedPlanFile
            fgwPlanFileWithoutMacroCells
            fgwCertExpiryFile
            fapCertExpiryFile
            fapScanResultFile
            fgwFcodesPlanFile
            fgwInseePlanFile
            fgwMacroDBPlanFile
            fgwFapsIpSecConnFailureFile
            fgwSecurityClonedHnbFile
        :param plan_id:  Configuration change plan number [0..4294967295]
            In case of allConfigurationPlanFile(12) file type, this parameter should be identical to
            the id attribute value inside the cmData element of to-be-downloaded XML file
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +------------------+--------------------------+------------+
        |                          Examples                        |
        +==================+==========================+============+
        | request activate | allConfigurationPlanFile | 3221225472 |
        +------------------+--------------------------+------------+
        | request activate | allConfigurationPlanFile | 3221225472 |
        +------------------+--------------------------+------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        file_type = self._map_filename_to_filetype(file_name)
        self._assert(self._get_emssim().cmd_file_activate().run([file_type, planid]), "File activate operation failed")

    def _map_filename_to_filetype(self, file_name):

        file_dict = {
            'hwconfigurationfile': 1,
            'configurationplanfile': 2,
            'logfile': 3,
            'swfile': 4,
            'licfile': 5,
            'measurementfile': 6,
            'rnwconfigurationplanfile': 7,
            'signalingplanfile': 8,
            'ipplanfile': 9,
            'alarmfile': 10,
            'combinedsiteconfigurationplanfile': 11,
            'allconfigurationplanfile': 12,
            'locationlock': 13,
            'testresultfile': 14,
            'autoconfreport': 15,
            'connectedfapinfofile': 16,
            'measurementplanfile': 17,
            'rnwmetadatafile': 18,
            'topologyfile': 19,
            'atmplanfile': 20,
            'subtopologyfile': 21,
            'togglingparfile': 22,
            'troubleshootingdata': 23,
            'faptmplfile': 24,
            'iprangefile': 25,
            'ipsecplanfile': 26,
            'fapconfiguredplanfile': 27,
            'fapactivatedplanfile': 28,
            'fgwplanfilewithoutmacrocells': 29,
            'fgwcertexpiryfile': 30,
            'fapcertexpiryfile': 31,
            'fapscanresultfile': 32,
            'fgwfcodesplanfile': 33,
            'fgwinseeplanfile': 34,
            'fgwmacrodbplanfile': 35,
            'fgwfapsipsecconnfailurefile': 36,
            'fgwsecurityclonedhnbfile': 37
        }
        self._assert(isinstance(file_name, six.string_types), "Wrong type! file_name should be string")
        self._assert(file_name.lower() in file_dict, "Wrong file name!")

        return file_dict[file_name.lower()]
